        jdbc.update("INSERT INTO plan (sheet, person_id, amount, start_date, every_days, month_day, end_date)"
                + " VALUES (?, ?, ?, ?, ?, ?, ?)", sheet, person, amount, Date.valueOf(start), every, day, Date.valueOf(end));
