import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's plan: an amount (two decimals), from `start` every `every` days (or, when `day` is set,
 *  monthly on that day of the month) to `end` (yyyy-MM-dd), and how many
 *  claims it has `generated` so far, and its `nextDates`: the first five plan dates after the sheet's
 *  today and on or before the end. */
export type Plan = { id: number; person: number; amount: string; start: string; every: number; end: string; generated: number;
  day: number | null; nextDates: string[] };

export const plansKey = (sheet: string) => ['plans', sheet] as const;

export const plansPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/plans`;

/** Every plan on the sheet, in the order added. */
export function usePlans(sheet: string) {
  return useQuery({
    queryKey: plansKey(sheet),
    queryFn: () => getJson<Plan[]>(plansPath(sheet)),
  });
}
import { useState, type FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { peoplePath } from '../people/people';
import type { Person } from '../people/people';
import { claimsKey } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { plansKey, plansPath, usePlans } from './plans';
import type { Plan } from './plans';

type PlanForm = { amount: string; start: string; every: string; day: string; end: string };

const EMPTY: PlanForm = { amount: '', start: '', every: '', day: '', end: '' };

function PlansHeader() {
  return <th>Plans</th>;
}

// A person's plans, each with how many claims it has made so far and its next five dates after the sheet's today, and the form adding one: an amount (0.00 or more,
// up to two decimals), a start date (blank: the sheet's today), every N days (a whole number, at least 1) or monthly
// on a day of the month (1 to 31, filled instead of every), and an end date not before the start. The server refuses anything else.
