    mutationFn: (body: PlanForm) => postJson<Plan[]>(byUser(`${peoplePath(sheet)}/${person.id}/plans`, user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(plansKey(sheet), updated);
      setForm(EMPTY);
    },
  });
